// Фильтруем строки, где есть номер тикета (начиная со 2-й строки)
const items = $input.all();
const filtered = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const ticketNumber = item.json['№ Тикета'];
  // Пропускаем первую строку (заголовки) и берем только строки с тикетами
  if (i > 0 && ticketNumber && ticketNumber !== '' && ticketNumber !== null && ticketNumber !== undefined) {
    filtered.push(item);
  }
}

return filtered;

// Подготовка данных для первого расчета
const item = $input.item.json;

const dataToSave = {
  ...item,
  calculationType: 'first'
};

// Кодируем JSON в base64 для безопасной передачи через аргументы
const jsonString = JSON.stringify(dataToSave);
const base64Data = Buffer.from(jsonString).toString('base64');

return {
  json: {
    ...item,
    calculationType: 'first',
    base64Data: base64Data
  }
};

// Подготовка данных для второго расчета
const item = $input.item.json;

const dataToSave = {
  ...item,
  calculationType: 'second'
};

// Кодируем JSON в base64 для безопасной передачи через аргументы
const jsonString = JSON.stringify(dataToSave);
const base64Data = Buffer.from(jsonString).toString('base64');

return {
  json: {
    ...item,
    calculationType: 'second',
    base64Data: base64Data
  }
};

// Парсим результат из вывода команды
const item = $input.item.json;
const stdout = item.stdout || '';

try {
  const result = JSON.parse(stdout.trim());
  return {
    json: {
      ...item,
      result: result.result || result.error || 'Ошибка расчета',
      success: result.success || false
    }
  };
} catch (error) {
  return {
    json: {
      ...item,
      result: stdout || 'Ошибка парсинга результата',
      success: false
    }
  };
}

